import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Method,
	Prop,
	Watch,
	h,
} from "@stencil/core";
import { caretRight } from "../../../icons";
import { focusVisible } from "../../utils/focus-visible";
import getBootstrapConfig from "../../utils/getBootstrapConfig";

let id = 0;

/**
 * @since 2.0
 * @status experimental
 *
 * @slot - The tab's label.
 *
 * @part base - The component's base wrapper.
 */

@Component({
	tag: "hbr-tab-fold",
	styleUrl: "tab-fold.scss",
	shadow: true,
})
export class TabFold {
	sheet: CSSStyleSheet = new CSSStyleSheet();
	componentId = `tab-fold-${++id}`;
	tabFold: HTMLElement;
	foldTabs: HTMLElement;
	tabFoldLabel: HTMLElement;

	@Element() host: HTMLHbrTabFoldElement;

	/** The name of the tab panel the tab will control. The panel must be located in the same tab group. */
	@Prop({ reflect: true }) panel = "";

	/** Set to true to draw the tab in an active state. */
	@Prop({ reflect: true, mutable: true }) active = false;

	/** Set to true to hide the right arrow. */
	@Prop({ reflect: true, mutable: true }) noRightArrow = false;

	/** When true, the tab-fold will be open when true. */
	@Prop({ reflect: true, mutable: true }) open = false;

	/** Set to true to draw the tab in a disabled state. */
	@Prop({ reflect: true }) disabled = false;

	@Prop({ mutable: true, reflect: true }) sentiment;

	/** deprecated */
	@Prop({ mutable: true, reflect: true }) arialabelledby = "";

	/** deprecated */
	@Prop({ mutable: true, reflect: true }) menuArialabelledby = "";

	/** role */
	@Prop({ reflect: true }) ariarole = "";

	/** Vertical tabs can be grouped with category labels that can remain static to display tab groupings. */
	@Prop({ reflect: true }) static = false;

	/** Emitted when the tab-fold is open */
	@Event({ eventName: "hbr-open" }) hbrOpen: EventEmitter;

	connectedCallback() {
		this.handleActiveState = this.handleActiveState.bind(this);
	}

	/** Sets focus to the tab. */
	@Method()
	async setFocus(options?: FocusOptions) {
		this.tabFoldLabel?.focus(options);
	}

	/** Removes focus from the tab. */
	@Method()
	async removeFocus() {
		this.tabFoldLabel?.blur();
	}

	@Watch("static")
	watchStatic() {
		this.open = true;
	}

	componentWillLoad() {
		if (this.static) {
			this.open = true;
		}
	}

	componentDidLoad() {
		this.handleActiveState();
		this.setNestedTabindex();
		focusVisible.observe(this.tabFold);
	}

	disconnectedCallback() {
		focusVisible.unobserve(this.tabFold);
	}

	handleActiveState() {
		if (this.foldTabs && !this.open) {
			this.active = this.hasNestedTabActive(this.foldTabs);
		}
	}

	handleOpen = () => {
		if (this.static) return;
		if (this.disabled) return;
		if (this.foldTabs) {
			this.open = !this.open;
			if (this.open) {
				this.active = false;
			} else {
				this.active = this.hasNestedTabActive(this.foldTabs);
			}
			this.setNestedTabindex();
			this.hbrOpen.emit({ open: this.open, fold: this.host });
		}
	};

	onKeyDownMenu = (event: KeyboardEvent) => {
		const target = event.target as HTMLHbrTabElement;
		if (this.static) {
			const tabVertical = this.host.closest(
				"hbr-tab-vertical[variant='nested']",
			) as HTMLHbrTabVerticalElement;
			if (tabVertical) {
				const tabs = Array.from(
					tabVertical.querySelectorAll(
						':scope > hbr-tab:not([disabled]):not([slot="content"]), :scope > :not([slot="content"]) hbr-tab:not([disabled])',
					),
				) as HTMLHbrTabElement[];
				let index = tabs.indexOf(target);

				if (!tabs.length) return;
				if (event.key === "ArrowUp") {
					event.stopPropagation();
					index = Math.max(0, index - 1);
					const tab = tabs[index];
					tab?.setFocus({ preventScroll: true });
					event.preventDefault();
				} else if (event.key === "ArrowDown") {
					event.stopPropagation();
					index = Math.min(tabs.length - 1, index + 1);
					const tab = tabs[index];
					tab?.setFocus({ preventScroll: true });
					event.preventDefault();
				}
			}
			return;
		}
		if (["ArrowUp", "ArrowDown"].includes(event.key)) {
			event.stopPropagation();
			const tabs = Array.from(
				this.host.querySelectorAll("hbr-tab:not([disabled])"),
			) as [HTMLHbrTabElement];
			let index = tabs.indexOf(target);

			if (!tabs.length) return;
			if (event.key === "ArrowUp") {
				index = Math.max(0, index - 1);
			} else if (event.key === "ArrowDown") {
				index = Math.min(tabs.length - 1, index + 1);
			}

			const tab = tabs[index];
			tab?.setFocus({ preventScroll: true });

			event.preventDefault();
		} else if (event.key === "Escape") {
			this.handleOpen();
			this.setFocus();
		}
	};
	onKeyDown = (event: KeyboardEvent) => {
		if (["Enter", " ", "Space"].includes(event.key)) {
			event.preventDefault();
			this.handleOpen();
		} else if (event.key === "ArrowDown") {
			if (this.open) {
				event.stopPropagation();
				const tabs = Array.from(
					this.host.querySelectorAll("hbr-tab:not([disabled])"),
				) as [HTMLHbrTabElement];
				tabs.length && tabs[0].setFocus({ preventScroll: true });
			}
		}
	};

	getAllTabs = (ele: HTMLHbrTabElement | HTMLElement) => {
		const slot = ele?.querySelector("slot");
		if (!slot) return [];
		return [...slot.assignedElements()].filter(
			(ele) => ele.tagName.toLowerCase() === "hbr-tab",
		);
	};

	setNestedTabindex = () => {
		const list = this.getAllTabs(this.foldTabs);
		return list.forEach((tab: HTMLHbrTabElement) => {
			tab.setTabindex();
		});
	};

	hasNestedTabActive = (ele: HTMLHbrTabElement | HTMLElement) => {
		const list = this.getAllTabs(ele);
		return list.some((tab: HTMLHbrTabElement) => tab?.active);
	};

	render() {
		let isNested = false;
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		let props = {};
		if (!this.static) {
			props = {
				tabindex: this.disabled ? "-1" : this.active ? "0" : "-1",
				onClick: this.handleOpen,
				onKeyDown: this.onKeyDown,
				onFocus: (e: FocusEvent) => {
					const ele = e.currentTarget as HTMLElement;
					ele.querySelector("hbr-button")?.setFocus();
				},
			};
			const parent = this.host.closest("hbr-tab-vertical");
			if (parent && parent.variant !== "nested") {
				props = {
					...props,
					role: this.ariarole || "tab",
					"aria-haspopup": "menu",
					"aria-disabled": this.disabled ? "true" : "false",
				};
			}
			isNested = parent && parent.variant === "nested" ? true : false;
			if (isNested) {
				parent.getTabFolds().then((folds) => {
					if (folds.includes(this.host)) {
						this.host.setAttribute(
							"aria-expanded",
							this.open ? "true" : "false",
						);
					}
				});
			}
		}
		return (
			// If the user didn't provide an ID, we'll set one so we can link tabs and tab panels with aria labels
			<Host id={this.host.id || this.componentId}>
				<div
					part="base"
					ref={(el) => {
						this.tabFold = el;
					}}
					class={{
						"tab-fold": true,

						// States
						"tab-fold--active": this.active,
						"tab-fold--open": this.open,
						"tab-fold--disabled": this.disabled,
						"tab-fold--static": this.static,
					}}
				>
					{this.active && !this.open && (
						<span part="indicator" class="tab-fold__vertical-indicator" />
					)}
					<div
						part="label"
						class="tab-fold--label"
						ref={(ref) => {
							this.tabFoldLabel = ref;
						}}
						{...props}
					>
						<span>
							<slot name="label" />
						</span>
						{this.static || this.noRightArrow ? null : (
							<div class="tab-fold__arrow-right">
								<hbr-button
									data-testid="tab-fold-button"
									variant="text"
									size="small"
									disabled={this.disabled}
									aria={{ label: this.open ? "Collapse" : "Expand" }}
								>
									<hbr-icon
										asset={customSystemIcons?.["caret-right"] || caretRight}
										exportparts="base:open-button"
									/>
								</hbr-button>
							</div>
						)}
					</div>
					<div
						part="tabs"
						class="tab-fold--tabs"
						aria-hidden={this.open ? "false" : "true"}
						role={isNested ? "group" : "menu"}
						onKeyDown={this.onKeyDownMenu}
						ref={(r) => {
							this.foldTabs = r;
						}}
					>
						<slot />
					</div>
				</div>
			</Host>
		);
	}
}
